        for hi in (3, 1000, 10**9):
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(5000)]))
    tests.append(fmt(list(range(1, 5001))))
    tests.append(fmt([rng.randint(0, 2) for _ in range(5000)]))
    return tests

